import{z as i,x as s,o as E,c as p,q as t,j as A,D as r,d as o,s as l,S as B,b as a}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"Debreu 价值理论","description":"","frontmatter":{"title":"Debreu 价值理论","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/debreu-theory-of-value.md","filePath":"econ/debreu-theory-of-value.md","lastUpdated":1791413859000}'),d={name:"econ/debreu-theory-of-value.md"};function u(h,e,D,c,m,f){const n=s("Mermaid");return E(),p("div",null,[e[2]||(e[2]=t('<h1 id="debreu-价值理论" tabindex="-1">Debreu 价值理论 <a class="header-anchor" href="#debreu-价值理论" aria-label="Permalink to &quot;Debreu 价值理论&quot;">​</a></h1><div class="epigraph"><p>本书的目的，是对竞争经济均衡做一次公理化分析。</p><footer>—— Debreu, Theory of Value: An Axiomatic Analysis of Economic Equilibrium, Cowles Monograph 17, 1959</footer></div><p><a href="/econ/arrow-debreu-paper">上一课</a>（Arrow–Debreu 或有商品）。附录对照。<a href="/econ/arrow-debreu-paper">上一篇</a>钉的是 Arrow 证券对或有商品的降维。本篇对照 <strong>Debreu 1959 原书</strong>：把商品空间、偏好、生产、均衡与福利收成一套可引用的公理，而不是课堂版的盒与超平面口诀。主干<a href="/econ/welfare-theorems">福利两定理</a>与<a href="/econ/ge-existence">存在性</a>已经取用结论；这里看原书怎样把日期、地点、状态写进同一商品向量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>1954 年论文证明存在，但商品仍是抽象的 \\(\\mathbb{R}^L\\)。缺口是统一语言：同一套符号要同时覆盖跨期、空间与不确定，而不另起「宏观」或「金融」章节。Debreu 的解决是把商品定义为物理性质、地点、日期与事件的组合。价格是该空间上的线性函数。一旦接受这一定义，不确定与时间不再是新理论，只是 \\(L\\) 变大。</p><p><span class="marginnote">数字实例：把日期、地点写进下标，「同一支冰淇淋」就拆开了——2 种物理商品 × 12 个月份 × 2 个地点 = 48 种商品，\\(L\\) 从 2 变 48。夏天与冬天的冰淇淋、北京与三亚的冰淇淋本来就不是同一种东西，价格自然也可以不同；跨期、贸易、不确定都不需要新理论，只是下标变多。</span></p><p>原书明确走布尔巴基式的公理路线：先列消费集、偏好的连续性与凸性、生产集的闭凸与不可逆，再陈述均衡与帕累托，最后用角谷。它不是经济史，也不给算法。</p><p><span class="marginnote">Cowles 专著 17。九章从商品与价格写到不确定。存在性用角谷，不用布劳威尔对付对应。私有制经济（private ownership）把利润按股份分配，均衡定义里利润必须被分完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>商品空间是有限维欧氏空间。消费集闭、凸、下有界；偏好用完备、传递、连续、凸的预序（不必先写效用函数；效用是表示，不是原语——对照主干<a href="/econ/utility-representation">效用表示</a>）。生产集含 \\(0\\)、闭凸、不能免费生产。均衡是价格、消费与生产计划，使需求在预算上最优、生产利润最大、市场出清。福利两定理在局部非饱和与凸性下陈述；第二定理用分离超平面，转移是总额的。</p><p>不确定一章把事件树写进商品下标，正是上一篇 Arrow 证券的商品侧。书中不讨论证券的动态交易策略，也不讨论不完全市场。</p>',11)),(E(),A(B,null,{default:r(()=>[l(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20COMM%5B%22%E5%95%86%E5%93%81%3A%20%E6%80%A7%E8%B4%A8%20x%20%E5%9C%B0%20x%20%E6%97%B6%20x%20%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20PREF%5B%22%E8%BF%9E%E7%BB%AD%E5%87%B8%E9%A2%84%E5%BA%8F%22%5D%0A%20%20PREF%20--%3E%20EQ%5B%22%E7%A7%81%E6%9C%89%E5%88%B6%E5%9D%87%E8%A1%A1%22%5D%0A%20%20PROD%5B%22%E9%97%AD%E5%87%B8%E7%94%9F%E4%BA%A7%E9%9B%86%22%5D%20--%3E%20EQ%0A%20%20EQ%20--%3E%20FWT%5B%22%E4%B8%A4%E5%AE%9A%E7%90%86%20%2B%20%E8%A7%92%E8%B0%B7%E5%AD%98%E5%9C%A8%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[o("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,"机制是线性价格在凸性上的支撑。凸偏好使「更好的集合」可被超平面分开，价格于是既是出清信号又是福利支撑。公理化的代价是：凡凸性失败（不可分、规模报酬递增），存在与第二定理一起停。原书把失败留在假设里，不提供非凸存在的一般定理。",-1)),e[5]||(e[5]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：分离超平面像在两块不重叠的凸面团之间平放一把直尺——面团只要有一处凹陷，尺子就可能被卡住切不开。价格向量就是这把尺子的朝向；凸性保证了尺子总放得下，「市场一个价格向量同时支撑均衡与帕累托」这件事才成立。")],-1)),(E(),A(B,null,{default:r(()=>[l(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%81%8F%E5%A5%BD%E5%87%B8%EF%BC%9A%E6%9B%B4%E5%A5%BD%E7%9A%84%E9%9B%86%E5%90%88%E6%97%A0%E5%87%B9%E9%99%B7%22%5D%20--%3E%20B%5B%22%E4%B8%8A%E7%AD%89%E5%80%BC%E9%9B%86%E4%B8%8E%E9%A2%84%E7%AE%97%E9%9B%86%E4%B8%8D%E7%9B%B8%E4%BA%A4%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%88%86%E7%A6%BB%E8%B6%85%E5%B9%B3%E9%9D%A2%E4%BB%8E%E4%B8%AD%E9%97%B4%E5%88%87%E5%BC%80%E4%B8%A4%E8%80%85%22%5D%0A%20%20C%20--%3E%20D%5B%22%E4%BB%B7%E6%A0%BC%20%3D%20%E8%B6%85%E5%B9%B3%E9%9D%A2%E7%9A%84%E6%B3%95%E5%90%91%E9%87%8F%22%5D%0A%20%20D%20--%3E%20E%5B%22%E4%BB%B7%E6%A0%BC%E6%97%A2%E6%94%AF%E6%92%91%E5%9D%87%E8%A1%A1%E5%8F%88%E6%94%AF%E6%92%91%E7%A6%8F%E5%88%A9%E5%AE%9A%E7%90%86%22%5D%0A%20%20F%5B%22%E5%87%B8%E6%80%A7%E5%A4%B1%E8%B4%A5%EF%BC%9A%E4%B8%8D%E5%8F%AF%E5%88%86%E6%88%96%E8%A7%84%E6%A8%A1%E6%8A%A5%E9%85%AC%E9%80%92%E5%A2%9E%22%5D%20--%3E%20G%5B%22%E5%88%86%E7%A6%BB%E5%A4%B1%E6%95%88%EF%BC%8C%E5%AD%98%E5%9C%A8%E4%B8%8E%E7%AC%AC%E4%BA%8C%E5%AE%9A%E7%90%86%E5%81%9C%22%5D%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=t('<p>与 Arrow 1953/1964 的分工：Debreu 把状态写进商品；Arrow 说明可用证券结算购买力。两篇对照才构成「或有商品经济」的课堂缩写。主干若只引 1954 存在性，会漏掉商品定义本身。</p><h3 id="效用是表示-不是原始对象" tabindex="-1">效用是表示，不是原始对象 <a class="header-anchor" href="#效用是表示-不是原始对象" aria-label="Permalink to &quot;效用是表示，不是原始对象&quot;">​</a></h3><p>书的章节顺序禁止先写 \\(\\max u(x)\\)：先有商品空间上的偏好公理，连续效用是定理。主干第一课<a href="/econ/preference-choice">偏好</a>的禁令出自这里。货币在书中没有特殊地位；<a href="/econ/money-as-medium">货币层次</a>必须另找摩擦。柠檬、信号、银行全部在公理之外。读附录是为了看见主干从哪一组假设出发，不是把 1959 年专论插入微观课序中间。</p><p><span class="marginnote">Cowles Foundation Monograph 17, Wiley / Yale, 1959。与 1954 年 Econometrica 短文不是同一文献。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>原书有限维、有限代理人、完全市场。无限维商品（连续时间消费）、测度空间上的代理人、太阳黑子，都是后继文献。不要把《价值理论》读成已经包含 <a href="/econ/capm-theory">CAPM</a> 或 <a href="/econ/stochastic-discount-factor">SDF</a>——那些要再加偏好与证券结构。也不要在附录复述盒的图画：那是主干埃奇沃思课的教具。</p><p>下一篇附录离开完全信息的竞争，对照 Akerlof 1970 的柠檬市场原文。</p><p>Mas-Colell, Whinston and Green 是教学展开；Debreu 是公理核。不要在附录复述斯勒茨基或厂商供给——那些是主干已经写过的推导。</p><p>效用是表示定理，不是第 1 章的原始对象。主干偏好课禁止先写 \\(\\max u(x)\\)，出处在这本书。</p><p>货币、银行、柠檬不在书中。那些课程必须另加摩擦，不是 Debreu 的未完成章节。</p><p><span class="marginnote">常见误区：初学者拿到问题第一行就写 \\(\\max u(x)\\)。Debreu 的顺序相反：先在商品空间上列出偏好公理（完备、传递、连续、凸），效用函数是后来被表示定理「造出来」的记号。为什么在乎顺序——因为有些偏好根本造不出连续效用，先写 max 等于把结论偷用了。</span></p><p>有限维、有限代理人、完全市场是主场域。无限维与测度空间上的代理人是后继。</p><p>1954 年论文与 1959 年书不要混引成同一文献：一篇存在性短文，一本公理专论。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Debreu 1959：竞争均衡的公理化，商品含时、地、状态。</li><li>存在与两定理是书中定理，不是口诀；凸性是支撑价格的关键。</li><li>与 Arrow 证券文分工：商品定义 vs 证券实施。</li><li>出处：Debreu, <em>Theory of Value</em>, 1959。</li></ul>',15))])}const x=i(d,[["render",u]]);export{C as __pageData,x as default};
